// Universal KP Engine -- Placidus house cusps + the 243/2187-fold KP
// sub-lord/sub-sub-lord system.
//
// VERIFICATION (Session with Naveen, using a real reference chart -- Naveen
// K. Rai, 08/04/1973 11:45 IST, Bhopal, 23.2505N 77.4065E -- generated by
// onlinejyotish.com's KP Horoscope tool and cross-checked here):
//
// 1. Sub-lord/sub-sub-lord chain (getSubLordChain below): verified EXACT
//    MATCH against all 9 planets + Ascendant + all 12 house cusps from that
//    chart's own "KP Sub Lords - Planets" and "KP Sub Lords - Houses"
//    tables (22/22 matches, using the reference's own longitude values).
//    This confirms the 243-division algorithm (each nakshatra split into 9
//    Vimshottari-proportional sub-parts, starting from that nakshatra's own
//    star lord and cycling through the fixed dasha-lord sequence; each sub
//    further split the same way for the sub-sub-lord) is correct.
//
// 2. Placidus cusp geometry (solvePlacidusCusps below): verified
//    STRUCTURALLY correct -- computed Ascendant, MC, and cusps XI/XII/II/III
//    all differ from the reference chart's values by the SAME constant
//    offset (~0.096 degrees / ~5'47"), not by independent errors. A
//    constant offset across every cusp means the iterative semi-arc solve
//    itself is right; the only discrepancy is the ayanamsa constant used.
//
// RESOLVED (this session): the ~0.0965° offset was identified as the
// Lahiri-vs-Krishnamurti ayanamsa difference. This file now imports
// krishnamurtiAyanamsa() from astro.ts (= Lahiri - 0.0965°, calibrated
// against Naveen's own reference KP chart from onlinejyotish.com).
// ARCHITECTURE.md Section 4 requires exactly this: Krishnamurti scoped to
// KP only, never leaking into the app-wide Lahiri default.
//
// REMAINING CAVEAT: the correction constant was derived from a single
// reference chart at a single epoch (1973). See astro.ts's
// krishnamurtiAyanamsa() comment for the full caveat on epoch-sensitivity.

import { julianDayFromUtc, krishnamurtiAyanamsa, NAKSHATRA_NAMES } from "./astro";

const DEG = Math.PI / 180;
const norm360 = (x: number): number => ((x % 360) + 360) % 360;
const NAK_WIDTH = 360 / 27;

export const DEFAULT_AYANAMSA_CAVEAT =
  "Using Krishnamurti ayanamsa (Lahiri - 0.0965°), calibrated against a verified reference " +
  "KP chart (onlinejyotish.com). Calibration is from a single epoch (1973); a second reference " +
  "chart at a different date has not yet been tested.";

// ── Placidus house cusps ──

function raFromLongitude(lambdaDeg: number, obliquityRad: number): number {
  const lambda = lambdaDeg * DEG;
  const ra = Math.atan2(Math.cos(obliquityRad) * Math.sin(lambda), Math.cos(lambda)) / DEG;
  return norm360(ra);
}

function longitudeFromRA(raDeg: number, obliquityRad: number): number {
  const ra = raDeg * DEG;
  const lambda = Math.atan2(Math.sin(ra) / Math.cos(obliquityRad), Math.cos(ra)) / DEG;
  return norm360(lambda);
}

function declinationOfLongitude(lambdaDeg: number, obliquityRad: number): number {
  const lambda = lambdaDeg * DEG;
  return Math.asin(Math.sin(obliquityRad) * Math.sin(lambda)) / DEG;
}

function ascensionalDifference(declDeg: number, latRad: number): number {
  const decl = declDeg * DEG;
  const val = Math.tan(latRad) * Math.tan(decl);
  const clamped = Math.max(-1, Math.min(1, val));
  return Math.asin(clamped) / DEG;
}

/** Iterative Placidus solve for an "upper" (diurnal semi-arc) cusp -- XI (fraction 1/3) or XII (2/3). */
function solveUpperCusp(fraction: number, ramcDeg: number, obliquityRad: number, latRad: number): number {
  let H = norm360(ramcDeg + fraction * 90);
  for (let i = 0; i < 30; i++) {
    const lambda = longitudeFromRA(H, obliquityRad);
    const decl = declinationOfLongitude(lambda, obliquityRad);
    const AD = ascensionalDifference(decl, latRad);
    const Hnew = norm360(ramcDeg + fraction * (90 + AD));
    if (Math.abs(((Hnew - H + 540) % 360) - 180) < 1e-8) {
      H = Hnew;
      break;
    }
    H = Hnew;
  }
  return longitudeFromRA(H, obliquityRad);
}

/** Iterative Placidus solve for a "lower" (nocturnal semi-arc) cusp -- II (fraction 2/3) or III (1/3), measured back from the IC. */
function solveLowerCusp(fraction: number, ramcDeg: number, obliquityRad: number, latRad: number): number {
  const icRA = norm360(ramcDeg + 180);
  let H = norm360(icRA - fraction * 90);
  for (let i = 0; i < 30; i++) {
    const lambda = longitudeFromRA(H, obliquityRad);
    const decl = declinationOfLongitude(lambda, obliquityRad);
    const AD = ascensionalDifference(decl, latRad);
    const Hnew = norm360(icRA - fraction * (90 - AD));
    if (Math.abs(((Hnew - H + 540) % 360) - 180) < 1e-8) {
      H = Hnew;
      break;
    }
    H = Hnew;
  }
  return longitudeFromRA(H, obliquityRad);
}

export interface PlacidusCusps {
  /** Index 0 = cusp I (Ascendant) ... index 11 = cusp XII. Sidereal (Lahiri) degrees, 0-360. */
  cusps: number[];
}

/**
 * All 12 Placidus house cusps, sidereal (Krishnamurti ayanamsa).
 * Structurally verified against Naveen's reference KP chart; now uses
 * krishnamurtiAyanamsa() per ARCHITECTURE.md Section 4.
 */
export function solvePlacidusCusps(birthUtc: Date, latitudeDeg: number, longitudeDeg: number): PlacidusCusps {
  const jd = julianDayFromUtc(birthUtc);
  const T = (jd - 2451545) / 36525;
  const gmst = norm360(
    280.46061837 + 360.98564736629 * (jd - 2451545) + 0.000387933 * T * T - (T * T * T) / 38710000
  );
  const ramcDeg = norm360(gmst + longitudeDeg);
  const obliquityDeg = 23.439291111 - 0.013004167 * T - 0.0000001639 * T * T;
  const obliquityRad = obliquityDeg * DEG;
  const latRad = latitudeDeg * DEG;
  // ARCHITECTURE.md Section 4: KP module uses Krishnamurti, not Lahiri.
  const ayanamsa = krishnamurtiAyanamsa(jd);

  // Ascendant -- same verified closed-form as lib/astro.ts / lib/lagna.ts.
  const ramc = ramcDeg * DEG;
  const tropicalAsc = norm360(
    Math.atan2(
      Math.cos(ramc),
      -(Math.sin(ramc) * Math.cos(obliquityRad) + Math.tan(latRad) * Math.sin(obliquityRad))
    ) / DEG
  );
  const tropicalMC = norm360(Math.atan2(Math.sin(ramc), Math.cos(ramc) * Math.cos(obliquityRad)) / DEG);

  const cuspXI = solveUpperCusp(1 / 3, ramcDeg, obliquityRad, latRad);
  const cuspXII = solveUpperCusp(2 / 3, ramcDeg, obliquityRad, latRad);
  const cuspII = solveLowerCusp(2 / 3, ramcDeg, obliquityRad, latRad);
  const cuspIII = solveLowerCusp(1 / 3, ramcDeg, obliquityRad, latRad);

  const tropical = [
    tropicalAsc, // I
    cuspII, // II
    cuspIII, // III
    norm360(tropicalMC + 180), // IV (IC)
    norm360(cuspXI + 180), // V (opposite XI)
    norm360(cuspXII + 180), // VI (opposite XII)
    norm360(tropicalAsc + 180), // VII
    norm360(cuspII + 180), // VIII
    norm360(cuspIII + 180), // IX
    tropicalMC, // X
    cuspXI, // XI
    cuspXII, // XII
  ];

  const cusps = tropical.map((deg) => norm360(deg - ayanamsa));
  return { cusps };
}

// ── KP sub-lord / sub-sub-lord chain ──

/** Fixed Vimshottari lord sequence and years -- same as lib/astro.ts's DASHA_SEQ/DASHA_YEARS,
 *  duplicated here to keep this file's sub-lord math self-contained and independently readable. */
const SEQ = ["Ketu", "Venus", "Sun", "Moon", "Mars", "Rahu", "Jupiter", "Saturn", "Mercury"];
const YEARS: Record<string, number> = {
  Ketu: 7,
  Venus: 20,
  Sun: 6,
  Moon: 10,
  Mars: 7,
  Rahu: 18,
  Jupiter: 16,
  Saturn: 19,
  Mercury: 17,
};
const TOTAL_YEARS = 120;

interface DivideResult {
  lord: string;
  lordSeqIdx: number;
  rangeStartDeg: number;
  rangeWidthDeg: number;
}

/** Splits `widthDeg` into 9 Vimshottari-proportional parts starting at `startSeqIdx`,
 *  and returns which part `posInWidthDeg` falls into. */
function divideBySeq(startSeqIdx: number, widthDeg: number, posInWidthDeg: number): DivideResult {
  let cum = 0;
  for (let i = 0; i < 9; i++) {
    const lordSeqIdx = (startSeqIdx + i) % 9;
    const lord = SEQ[lordSeqIdx]!;
    const w = (YEARS[lord]! / TOTAL_YEARS) * widthDeg;
    if (posInWidthDeg < cum + w || i === 8) {
      return { lord, lordSeqIdx, rangeStartDeg: cum, rangeWidthDeg: w };
    }
    cum += w;
  }
  // Unreachable (i === 8 branch above always returns), kept for TS exhaustiveness.
  throw new Error("divideBySeq: fell through 9-part loop unexpectedly.");
}

export interface SubLordChain {
  nakshatraIdx: number;
  nakshatraName: string;
  /** The nakshatra's own ruling planet -- the classical "star lord." */
  starLord: string;
  subLord: string;
  subSubLord: string;
}

/**
 * Given a sidereal longitude (0-360), returns its nakshatra, star lord, KP
 * sub-lord, and sub-sub-lord. Verified 22/22 against a real reference chart
 * -- see file header.
 */
export function getSubLordChain(siderealLonDeg: number): SubLordChain {
  const lon = norm360(siderealLonDeg);
  const nakshatraIdx = Math.floor(lon / NAK_WIDTH);
  const starLordSeqIdx = nakshatraIdx % 9;
  const posInNak = lon - nakshatraIdx * NAK_WIDTH;

  const subDiv = divideBySeq(starLordSeqIdx, NAK_WIDTH, posInNak);
  const subSubDiv = divideBySeq(subDiv.lordSeqIdx, subDiv.rangeWidthDeg, posInNak - subDiv.rangeStartDeg);

  return {
    nakshatraIdx,
    nakshatraName: NAKSHATRA_NAMES[nakshatraIdx]!,
    starLord: SEQ[starLordSeqIdx]!,
    subLord: subDiv.lord,
    subSubLord: subSubDiv.lord,
  };
}
